1: #import <UIKit/UIKit.h>
2: #include <math.h>
3: #import <CoreFoundation/CoreFoundation.h>
4: #import <notify.h>
5: static CFStringRef const kDomain = CFSTR("com.tu.recordingsharingan.settings");
6: @interface RSHandoffController : UIViewController
7: @property(nonatomic,strong) UISwitch *enabledSwitch;
8: @property(nonatomic,strong) UISlider *slider;
9: @property(nonatomic,strong) UILabel *numberLabel;
10: @property(nonatomic,strong) UIButton *minusButton;
11: @property(nonatomic,strong) UIButton *plusButton;
12: @end
13: @implementation RSHandoffController
14: - (id)initForContentSize:(CGSize)size { return [self init]; }
15: - (void)loadView {
16:     [super loadView];
17:     self.title = @"灵动岛接续调节";
18:     UIView *root=self.view; root.backgroundColor=[UIColor systemGroupedBackgroundColor];
19:     UIView *panel=[UIView new]; panel.translatesAutoresizingMaskIntoConstraints=NO;
20:     panel.backgroundColor=[UIColor secondarySystemGroupedBackgroundColor]; panel.layer.cornerRadius=15;
21:     [root addSubview:panel];
22:     UILabel *header=[UILabel new]; header.text=@"手动调节首次检查等待"; header.font=[UIFont boldSystemFontOfSize:17]; header.translatesAutoresizingMaskIntoConstraints=NO; [panel addSubview:header];
23:     UISwitch *toggle=[UISwitch new]; self.enabledSwitch=toggle; toggle.translatesAutoresizingMaskIntoConstraints=NO; [toggle addTarget:self action:@selector(toggleChanged:) forControlEvents:UIControlEventValueChanged]; [panel addSubview:toggle];
24:     UILabel *number=[UILabel new]; self.numberLabel=number; number.textAlignment=NSTextAlignmentCenter; number.font=[UIFont monospacedDigitSystemFontOfSize:36 weight:UIFontWeightSemibold]; number.translatesAutoresizingMaskIntoConstraints=NO; [panel addSubview:number];
25:     UISlider *slider=[UISlider new]; self.slider=slider; slider.minimumValue=10; slider.maximumValue=150; slider.translatesAutoresizingMaskIntoConstraints=NO; [slider addTarget:self action:@selector(sliderChanged:) forControlEvents:UIControlEventValueChanged]; [panel addSubview:slider];
26:     UIButton *minus=[UIButton buttonWithType:UIButtonTypeSystem]; self.minusButton=minus; [minus setTitle:@"−" forState:UIControlStateNormal]; minus.titleLabel.font=[UIFont boldSystemFontOfSize:30]; minus.translatesAutoresizingMaskIntoConstraints=NO; [minus addTarget:self action:@selector(decrease) forControlEvents:UIControlEventTouchUpInside]; [panel addSubview:minus];
27:     UIButton *plus=[UIButton buttonWithType:UIButtonTypeSystem]; self.plusButton=plus; [plus setTitle:@"+" forState:UIControlStateNormal]; plus.titleLabel.font=[UIFont boldSystemFontOfSize:30]; plus.translatesAutoresizingMaskIntoConstraints=NO; [plus addTarget:self action:@selector(increase) forControlEvents:UIControlEventTouchUpInside]; [panel addSubview:plus];
28:     UIButton *reset=[UIButton buttonWithType:UIButtonTypeSystem]; [reset setTitle:@"恢复 V7.11.9.4 默认时序" forState:UIControlStateNormal]; reset.translatesAutoresizingMaskIntoConstraints=NO; [reset addTarget:self action:@selector(resetDefaults) forControlEvents:UIControlEventTouchUpInside]; [panel addSubview:reset];
29:     UILabel *note=[UILabel new]; note.text=@"10–150ms，每次 ±5ms。仅改变首次宿主检查；身份验证、二次确认、420ms 防抢占保护不变。若调快无效，请恢复默认。"; note.numberOfLines=0; note.font=[UIFont systemFontOfSize:13]; note.textColor=[UIColor secondaryLabelColor]; note.translatesAutoresizingMaskIntoConstraints=NO; [root addSubview:note];
30:     [NSLayoutConstraint activateConstraints:@[
31:         [panel.topAnchor constraintEqualToAnchor:root.safeAreaLayoutGuide.topAnchor constant:20], [panel.leadingAnchor constraintEqualToAnchor:root.leadingAnchor constant:16], [panel.trailingAnchor constraintEqualToAnchor:root.trailingAnchor constant:-16], [panel.heightAnchor constraintEqualToConstant:270],
32:         [header.topAnchor constraintEqualToAnchor:panel.topAnchor constant:22], [header.leadingAnchor constraintEqualToAnchor:panel.leadingAnchor constant:16],
33:         [toggle.centerYAnchor constraintEqualToAnchor:header.centerYAnchor], [toggle.trailingAnchor constraintEqualToAnchor:panel.trailingAnchor constant:-16],
34:         [number.centerXAnchor constraintEqualToAnchor:panel.centerXAnchor], [number.topAnchor constraintEqualToAnchor:header.bottomAnchor constant:24],
35:         [slider.leadingAnchor constraintEqualToAnchor:minus.trailingAnchor constant:8], [slider.trailingAnchor constraintEqualToAnchor:plus.leadingAnchor constant:-8], [slider.centerYAnchor constraintEqualToAnchor:minus.centerYAnchor],
36:         [minus.leadingAnchor constraintEqualToAnchor:panel.leadingAnchor constant:15], [minus.topAnchor constraintEqualToAnchor:number.bottomAnchor constant:15], [minus.widthAnchor constraintEqualToConstant:40],
37:         [plus.trailingAnchor constraintEqualToAnchor:panel.trailingAnchor constant:-15], [plus.centerYAnchor constraintEqualToAnchor:minus.centerYAnchor], [plus.widthAnchor constraintEqualToConstant:40],
38:         [reset.centerXAnchor constraintEqualToAnchor:panel.centerXAnchor], [reset.topAnchor constraintEqualToAnchor:minus.bottomAnchor constant:24],
39:         [note.topAnchor constraintEqualToAnchor:panel.bottomAnchor constant:14], [note.leadingAnchor constraintEqualToAnchor:panel.leadingAnchor constant:8], [note.trailingAnchor constraintEqualToAnchor:panel.trailingAnchor constant:-8]
40:     ]];
41: }
42: - (void)viewWillAppear:(BOOL)animated { [super viewWillAppear:animated]; [self loadSettings]; }
43: - (void)loadSettings {
44:     CFPropertyListRef flag=CFPreferencesCopyAppValue(CFSTR("handoffManualEnabled"),kDomain);
45:     self.enabledSwitch.on=(flag && CFGetTypeID(flag)==CFBooleanGetTypeID() && CFBooleanGetValue((CFBooleanRef)flag)); if(flag)CFRelease(flag);
46:     CFPropertyListRef val=CFPreferencesCopyAppValue(CFSTR("handoffDelayMs"),kDomain); int n=40;
47:     if(val && CFGetTypeID(val)==CFNumberGetTypeID())CFNumberGetValue((CFNumberRef)val,kCFNumberIntType,&n); if(val)CFRelease(val);
48:     self.slider.value=MAX(10,MIN(150,n)); [self refresh];
49: }
50: - (void)saveNumber:(int)n { n=MAX(10,MIN(150,n)); self.slider.value=n; CFNumberRef v=CFNumberCreate(kCFAllocatorDefault,kCFNumberIntType,&n); CFPreferencesSetAppValue(CFSTR("handoffDelayMs"),v,kDomain); CFRelease(v); [self synchronize]; [self refresh]; }
51: - (void)synchronize { CFPreferencesAppSynchronize(kDomain); notify_post("com.tu.recordingsharingan.settings.changed"); }
52: - (void)refresh { int n=(int)(roundf(self.slider.value/5.f)*5); self.numberLabel.text=[NSString stringWithFormat:@"%d ms",n]; BOOL on=self.enabledSwitch.on; self.slider.enabled=on; self.minusButton.enabled=on && n>10; self.plusButton.enabled=on && n<150; }
53: - (void)toggleChanged:(UISwitch *)sender { CFPreferencesSetAppValue(CFSTR("handoffManualEnabled"),sender.on?kCFBooleanTrue:kCFBooleanFalse,kDomain); [self synchronize]; [self refresh]; }
54: - (void)sliderChanged:(UISlider *)sender { [self saveNumber:(int)(roundf(sender.value/5.f)*5)]; }
55: - (void)decrease { [self saveNumber:(int)(roundf(self.slider.value/5.f)*5)-5]; }
56: - (void)increase { [self saveNumber:(int)(roundf(self.slider.value/5.f)*5)+5]; }
57: - (void)resetDefaults { self.enabledSwitch.on=NO; CFPreferencesSetAppValue(CFSTR("handoffManualEnabled"),kCFBooleanFalse,kDomain); [self saveNumber:40]; }
58: @end
